() => {
  const card = document.getElementById('card');
  const cr = card.getBoundingClientRect();
  const bad = [];
  document.querySelectorAll('#card *').forEach(el => {
    const r = el.getBoundingClientRect();
    if (r.width === 0 && r.height === 0) return;
    if (r.left < cr.left - 0.5 || r.right > cr.right + 0.5 || r.top < cr.top - 0.5 || r.bottom > cr.bottom + 0.5)
      bad.push([el.className || el.tagName, JSON.stringify(r)]);
    if (el.scrollWidth > el.clientWidth + 1 || el.scrollHeight > el.clientHeight + 1)
      bad.push(['scroll-overflow: ' + (el.className||el.tagName), el.scrollWidth+'/'+el.clientWidth+' '+el.scrollHeight+'/'+el.clientHeight]);
  });
  const p = document.querySelector('.portrait').getBoundingClientRect();
  return {size: document.body.className, bad, portrait: p.width + 'x' + p.height,
          scroll: [document.documentElement.scrollWidth, document.documentElement.scrollHeight]};
}

