async (page) => {
  const audit = () => {
    const card = document.getElementById('card');
    const cr = card.getBoundingClientRect();
    const out = [];
    document.querySelectorAll('#card *').forEach(el => {
      const r = el.getBoundingClientRect();
      if (!r.width && !r.height) return;
      if (r.left < cr.left - 0.5 || r.right > cr.right + 0.5 || r.top < cr.top - 0.5 || r.bottom > cr.bottom + 0.5)
        out.push('OUT_OF_BOUNDS ' + (el.className||el.tagName) + ' ' + JSON.stringify(r));
    });
    const p = document.querySelector('.portrait').getBoundingClientRect();
    const t = document.querySelector('.title').getBoundingClientRect();
    const f = document.querySelector('.footer').getBoundingClientRect();
    return {size: document.body.className, out, portrait: p.width+'x'+p.height,
            titleBottom: t.bottom, footerTop: f.top, gap: f.top - t.bottom,
            cardH: cr.height, cardW: cr.width};
  };
  const res = [];
  await page.setViewportSize({width:1080,height:1080});
  await page.goto('http://localhost:54218/card.html?size=square');
  await page.evaluate(() => document.fonts.ready);
  res.push(await page.evaluate(audit));
  await page.setViewportSize({width:1920,height:1080});
  await page.goto('http://localhost:54218/card.html?size=landscape');
  await page.evaluate(() => document.fonts.ready);
  res.push(await page.evaluate(audit));
  return res;
}

